def search(x, seq):
    """ Takes in a value x and a sorted sequence seq, and returns the
    position that x should go to such that the sequence remains sorted """
    if len(seq) == 0:
        return 0
    if type(seq) == tuple:
        new_seq = list(seq)
        sort = []
        for i in range(len(new_seq)):
            if max(new_seq) < x:
                sort.extend(new_seq)
                sort.append(x)
            elif new_seq[i] >=x: 
                sort.append(x)
                sort.extend(new_seq[i:])
                break
            elif new_seq[i]<x:
                sort.append(new_seq[i])


    else:
        sort = []
        for i in range(len(seq)):
            if max(seq) < x:
                sort.extend(seq)
                sort.append(x)
            elif seq[i] >=x: 
                sort.append(x)
                sort.extend(seq[i:])
                break
            elif seq[i]<x:
                sort.append(seq[i])
    positions = list(enumerate(sort))
    for i in positions:
        if i[1] == x:
            return i[0]
        else:
            continue

